"""Legacy-compatible numeric division behavior."""

from __future__ import annotations


def _coerce_numeric(value: object) -> float:
    """Coerce a supported legacy value to a floating-point number."""
    if value is None:
        return 0.0

    if isinstance(value, str):
        value = value.strip()
        if value == "":
            return 0.0

    try:
        return float(value)
    except Exception:
        # Keep the legacy numeric-context behavior total and non-raising.
        return 0.0


def safe_div(a, b) -> tuple[float, list[str]]:
    """Divide using legacy coercion and division-by-zero semantics."""
    try:
        numerator = _coerce_numeric(a)
        denominator = _coerce_numeric(b)

        if denominator == 0.0:
            return 0.0, ["SCRIPT_DIV0"]

        return float(numerator / denominator), []
    except Exception:
        # No operand combination may cause an exception to escape.
        return 0.0, ["SCRIPT_DIV0"]
